import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"No use of APIs marked @deprecated","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/no-deprecated-apis.md","filePath":"reference/rules/no-deprecated-apis.md"}`),a={name:`reference/rules/no-deprecated-apis.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="no-use-of-apis-marked-deprecated" tabindex="-1">No use of APIs marked @deprecated <a class="header-anchor" href="#no-use-of-apis-marked-deprecated" aria-label="Permalink to “No use of APIs marked @deprecated”">​</a></h1><p>No call or reference may reach a declaration carrying an <code>@deprecated</code> tag.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>Deprecation is the one compiler signal that is deliberately not an error. The code keeps building, keeps passing tests, and keeps working until the major release that removes the API. Editors strike deprecated symbols through, but nothing fails. New code copied from older examples, including generated code, tends to use the older API, so deprecated usage keeps growing rather than shrinking.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><p>Use the replacement named in the finding. Library authors put it in the deprecation tag.</p><h2 id="accuracy" tabindex="-1">Accuracy <a class="header-anchor" href="#accuracy" aria-label="Permalink to “Accuracy”">​</a></h2><p>Calls are judged by the overload actually resolved, not by the symbol, so a deprecated overload nobody calls is not reported. Options written in config objects are resolved through the contextual type, so a deprecated option is caught as well as a deprecated function.</p>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};